'use client';

import { FaStar, FaFlagCheckered, FaPuzzlePiece, FaTrophy } from 'react-icons/fa';

const quests = [
	{
		name: 'First Steps',
		desc: 'Complete your first checkpoint quest and get familiar with the event.',
		checkpoints: 10,
		icon: <FaFlagCheckered className="text-accent-purple text-3xl" />,
	},
	{
		name: 'Puzzle Master',
		desc: 'Solve the event puzzle to earn extra points.',
		checkpoints: 25,
		icon: <FaPuzzlePiece className="text-accent-blue text-3xl" />,
	},
	{
		name: 'Speed Runner',
		desc: 'Finish a quest in record time!',
		checkpoints: 15,
		icon: <FaTrophy className="text-accent-pink text-3xl" />,
	},
	{
		name: 'Star Collector',
		desc: 'Collect 5 stars from different activities.',
		checkpoints: 20,
		icon: <FaStar className="text-accent-green text-3xl" />,
	},
];

export default function QuestsPage() {
	return (
		<section className="content-section">
			<h2 className="text-4xl font-bold mb-8 bg-gradient-to-r from-purple-500 to-pink-500 bg-clip-text text-transparent">
				Quests
			</h2>
			<div className="grid md:grid-cols-2 gap-8">
				{quests.map((quest, idx) => (
					<div
						key={idx}
						className="bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900 rounded-xl p-6 shadow-lg border border-white/10 flex items-center gap-6 hover:scale-105 transition-transform"
					>
						<div className="shrink-0">{quest.icon}</div>
						<div>
							<h3 className="text-2xl font-semibold mb-1 text-accent-purple">
								{quest.name}
							</h3>
							<p className="text-text-gray mb-2">{quest.desc}</p>
							<span className="inline-flex items-center gap-1 px-3 py-1 rounded bg-gradient-to-r from-accent-purple to-accent-pink text-white font-bold text-sm">
								+{quest.checkpoints} Checkpoints
							</span>
						</div>
					</div>
				))}
			</div>
		</section>
	);
}

'use client';

import Image from 'next/image';
import { FaCoins, FaBoxOpen, FaCheckCircle } from 'react-icons/fa';

const storeItems = [
	{
		name: 'Checkpoint Hoodie',
		desc: 'Limited edition event hoodie. Stay warm and stylish!',
		img: '/static/icon.png',
		stock: 5,
		price: 100,
		icon: <FaBoxOpen className="text-accent-blue text-2xl" />,
	},
	{
		name: 'Mystery Box',
		desc: 'A box of surprise goodies. What will you get?',
		img: '/static/icon.png',
		stock: 10,
		price: 50,
		icon: <FaBoxOpen className="text-accent-pink text-2xl" />,
	},
	{
		name: 'VIP Badge',
		desc: 'Unlock special access and perks at the event.',
		img: '/static/icon.png',
		stock: 2,
		price: 200,
		icon: <FaCheckCircle className="text-accent-green text-2xl" />,
	},
];

export default function ShopPage() {
	return (
		<section className="content-section">
			<h2 className="text-4xl font-bold mb-8 bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text text-transparent">
				Store
			</h2>
			<div className="grid md:grid-cols-2 gap-8">
				{storeItems.map((item, idx) => (
					<div
						key={idx}
						className="bg-gradient-to-br from-slate-900 via-blue-900 to-slate-900 rounded-xl p-6 shadow-lg border border-white/10 flex items-center gap-6 hover:scale-105 transition-transform"
					>
						<div className="shrink-0">
							<Image
								src={item.img}
								alt={item.name}
								width={64}
								height={64}
								className="rounded-lg shadow-md"
							/>
						</div>
						<div className="flex-1">
							<h3 className="text-2xl font-semibold mb-1 text-accent-blue flex items-center gap-2">
								{item.icon} {item.name}
							</h3>
							<p className="text-text-gray mb-2">{item.desc}</p>
							<div className="flex gap-4 items-center mt-2">
								<span className="inline-flex items-center gap-1 px-3 py-1 rounded bg-gradient-to-r from-accent-blue to-accent-purple text-white font-bold text-sm">
									<FaCoins className="text-yellow-400" /> {item.price} Starting
									Bid
								</span>
								<span className="inline-flex items-center gap-1 px-3 py-1 rounded bg-gradient-to-r from-accent-green to-accent-blue text-white font-bold text-sm">
									Stock: {item.stock}
								</span>
							</div>
						</div>
					</div>
				))}
			</div>
		</section>
	);
}
